// tests/helpers/router.test.js
const { routeTask } = require('../../.claude/helpers/router.js');

describe('routeTask', () => {
  it.each([
    ['fix the authentication bug', 'coder'],
    ['write unit tests for auth', 'tester'],
    ['design the new API architecture', 'system-architect'],
    ['review this PR for security issues', 'security-auditor'],
    ['research how Redis pub/sub works', 'researcher'],
    ['optimize the database query performance', 'performance-engineer'],
  ])('routes "%s" to %s', (task, expectedAgent) => {
    const result = routeTask(task);
    expect(result.agent).toBe(expectedAgent);
    expect(result.confidence).toBeGreaterThan(0);
    expect(result.confidence).toBeLessThanOrEqual(1);
  });

  it('returns coder with 0.5 confidence for empty string', () => {
    const result = routeTask('');
    expect(result.agent).toBe('coder');
    expect(result.confidence).toBe(0.5);
  });

  it('is case-insensitive', () => {
    expect(routeTask('WRITE TESTS').agent).toBe(routeTask('write tests').agent);
  });
});
