**Untested:**
- `get` on missing key returns undefined
- `set` stores value with timestamp
- `delete` removes key
- `clear` wipes all non-underscore keys
- `keys` excludes `_`-prefixed internals
- Corrupt JSON file silently returns `{}`

```js
// tests/helpers/memory.test.js
const fs = require('fs');
const path = require('path');
const os = require('os');

let tmpDir, memoryModule;
beforeEach(() => {
  tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'memory-test-'));
  jest.resetModules();
  process.env.MEMORY_PATH = path.join(tmpDir, 'memory.json');
  memoryModule = require('../../.claude/helpers/memory.js');
});

describe('memory commands', () => {
  it('get returns undefined for missing key', () => {
    expect(memoryModule.commands.get('missing')).toBeUndefined();
  });

  it('set persists value with _timestamp', () => {
    memoryModule.commands.set('foo', 'bar');
    expect(memoryModule.commands.get('foo')).toBe('bar');
  });

  it('delete removes key', () => {
    memoryModule.commands.set('x', '1');
    memoryModule.commands.delete('x');
    expect(memoryModule.commands.get('x')).toBeUndefined();
  });

  it('clear wipes entries, keeps _meta keys intact', () => {
    memoryModule.commands.set('a', '1');
    memoryModule.commands.clear();
    expect(memoryModule.commands.keys()).toHaveLength(0);
  });

  it('returns empty object for corrupt JSON', () => {
    fs.writeFileSync(process.env.MEMORY_PATH, '{bad json}');
    jest.resetModules();
    const fresh = require('../../.claude/helpers/memory.js');
    expect(() => fresh.commands.keys()).not.toThrow();
  });
});
```

