**Untested:**
- `start()` creates session with ID + timestamp
- `restore()` on missing file returns null and logs
- `end()` archives session and calculates duration
- `status()` with no active session returns null
- `metric()` increments counter correctly
- Corrupt session file handled gracefully

```js
// tests/helpers/session.test.js
describe('session lifecycle', () => {
  it('start() creates session with id and startDate', () => {
    const session = commands.start();
    expect(session.id).toBeDefined();
    expect(session.startDate).toBeDefined();
  });

  it('restore() returns null when no session file exists', () => {
    const result = commands.restore();
    expect(result).toBeNull();
  });

  it('end() archives session and records durationMs', () => {
    commands.start();
    const archived = commands.end();
    expect(archived.durationMs).toBeGreaterThanOrEqual(0);
  });

  it('status() returns null without an active session', () => {
    expect(commands.status()).toBeNull();
  });

  it('metric() increments named counter', () => {
    commands.start();
    commands.metric('edits');
    commands.metric('edits');
    const s = commands.status();
    expect(s.metrics.edits).toBe(2);
  });
});
```

