**Untested:**
- `pre-bash` blocks known dangerous patterns (`rm -rf /`, `format c:`)
- `pre-bash` allows safe commands
- `route` returns a valid agent
- stdin timeout returns empty object (not throw)
- Unknown hook type is a no-op (exit 0)

```js
// tests/helpers/hook-handler.test.js
const { handlers } = require('../../.claude/helpers/hook-handler.cjs');

describe('pre-bash dangerous command detection', () => {
  it.each([
    'rm -rf /',
    'format c:',
    'dd if=/dev/zero of=/dev/sda',
    ':(){:|:&};:',
  ])('blocks "%s"', async (cmd) => {
    const result = await handlers['pre-bash']({ command: cmd });
    expect(result.block).toBe(true);
  });

  it('allows safe git commands', async () => {
    const result = await handlers['pre-bash']({ command: 'git status' });
    expect(result.block).toBeFalsy();
  });
});

describe('stdin timeout', () => {
  it('resolves to empty string after 500ms on empty stdin', async () => {
    const result = await readStdinWithTimeout(100);
    expect(result).toBe('');
  });
});
```

