**Untested:**
- `resolveBackend()` falls back: SQLite → RuVector → AgentDB → JSON
- `createHashEmbedding()` returns 384-dim array that sums correctly
- `chunkTranscript()` groups messages into turns
- `storeChunks()` deduplicates identical content
- Autopilot triggers prune at 85% context
- `parseTranscript()` returns `[]` for missing/corrupt file

```js
// tests/helpers/context-persistence.test.js
import { createHashEmbedding, chunkTranscript, parseTranscript }
  from '../../.claude/helpers/context-persistence-hook.mjs';

describe('createHashEmbedding', () => {
  it('returns 384-element array', () => {
    const emb = createHashEmbedding('hello world', 384);
    expect(emb).toHaveLength(384);
  });

  it('is deterministic for same input', () => {
    expect(createHashEmbedding('test', 384)).toEqual(createHashEmbedding('test', 384));
  });

  it('differs for different inputs', () => {
    expect(createHashEmbedding('a', 384)).not.toEqual(createHashEmbedding('b', 384));
  });
});

describe('chunkTranscript', () => {
  it('groups user+assistant pairs into turns', () => {
    const messages = [
      { role: 'user', content: 'q1' },
      { role: 'assistant', content: 'a1' },
      { role: 'user', content: 'q2' },
      { role: 'assistant', content: 'a2' },
    ];
    const chunks = chunkTranscript(messages);
    expect(chunks).toHaveLength(2);
  });
});

describe('parseTranscript', () => {
  it('returns [] for nonexistent file', () => {
    expect(parseTranscript('/no/such/file.json')).toEqual([]);
  });

  it('returns [] for malformed JSON', () => {
    const p = writeTempFile('{bad}');
    expect(parseTranscript(p)).toEqual([]);
  });
});

describe('resolveBackend fallback', () => {
  it('returns JsonFileBackend when all other tiers fail', async () => {
    // Mock SQLite, RuVector, AgentDB to throw
    const backend = await resolveBackend({ forceFail: ['sqlite', 'ruvector', 'agentdb'] });
    expect(backend.constructor.name).toBe('JsonFileBackend');
  });
});
```

