- `countFilesAndLines()` returns 0 for empty dir
- `calculateModuleProgress()` scores 0 when no files present
- `countProcesses()` returns zeros when `ps` fails
- `getMetricsJSON()` returns valid JSON structure

```js
// tests/helpers/metrics-db.test.js
describe('countFilesAndLines', () => {
  it('returns { files: 0, lines: 0 } for empty directory', async () => {
    const result = await countFilesAndLines(emptyDir, '.ts');
    expect(result).toEqual({ files: 0, lines: 0 });
  });

  it('counts lines across multiple files', async () => {
    writeFile(tmpDir, 'a.ts', 'line1\nline2\n');
    writeFile(tmpDir, 'b.ts', 'line1\n');
    const result = await countFilesAndLines(tmpDir, '.ts');
    expect(result.lines).toBe(3);
  });
});

describe('countProcesses when ps unavailable', () => {
  it('returns zeros on ps failure', () => {
    jest.spyOn(child_process, 'execSync').mockImplementation(() => { throw new Error(); });
    const result = countProcesses();
    expect(result).toEqual({ agenticFlow: 0, mcp: 0, agents: 0 });
  });
});
```

